#include <bits/stdc++.h>
using namespace std; using U=uint64_t;
struct Graph {string id;int n,k,m;vector<pair<int,int>> es;vector<int> ports;};
vector<Graph> readg(string fn){ifstream f(fn);if(!f)throw runtime_error("input open");int t;f>>t;vector<Graph> r(t);for(auto &g:r){f>>g.id>>g.n>>g.k>>g.m;g.ports.resize(g.k);for(auto &v:g.ports)f>>v;for(int j=0,a,b;j<g.m;j++){f>>a>>b;g.es.emplace_back(a,b);}}return r;}
U adj[64];int N;unsigned long long nodes=0,pruned[3]={},done=0,hits=0,pairsct=0;ofstream out;int limitn=100;vector<pair<int,int>> links;const Graph *ga,*gb;
bool path(int u,int t,int rem,U seen){if(rem==1)return adj[u]>>t&1;U m=adj[u]&~seen&~(1ULL<<t);while(m){int v=__builtin_ctzll(m);m&=m-1;if(path(v,t,rem-1,seen|(1ULL<<v)))return true;}return false;}
bool safeedge(int a,int b){int ls[]={3,7,15};for(int i=0;i<3;i++)if(path(a,b,ls[i],1ULL<<a)){pruned[i]++;return false;}return true;}
void save(){hits++;out<<ga->id<<" "<<gb->id<<" "<<N<<" "<<(3*N-3)/2<<"\n";for(int a=0;a<N;a++)for(int b=a+1;b<N;b++)if(adj[a]>>b&1)out<<a<<" "<<b<<"\n";out.flush();}
void rec(const vector<int>& left,int dep,int used){nodes++;if(dep==5){done++;save();return;}int a=left[dep];for(int j=0;j<7;j++){if(used>>j&1)continue;int b=gb->ports[j]+ga->n;if(!safeedge(a,b))continue;adj[a]|=1ULL<<b;adj[b]|=1ULL<<a;rec(left,dep+1,used|1<<j);adj[a]^=1ULL<<b;adj[b]^=1ULL<<a;}}
int main(int argc,char**argv){if(argc<4)return 2;auto A=readg(argv[1]),B=readg(argv[2]);out.open(argv[3]);if(argc>4)limitn=stoi(argv[4]);auto t=chrono::steady_clock::now();for(auto&a:A)for(auto&b:B){N=a.n+b.n;if(N>limitn||N>63)continue;ga=&a;gb=&b;fill(adj,adj+64,0);for(auto[x,y]:a.es){adj[x]|=1ULL<<y;adj[y]|=1ULL<<x;}for(auto[x,y]:b.es){x+=a.n;y+=a.n;adj[x]|=1ULL<<y;adj[y]|=1ULL<<x;}for(int omitted=0;omitted<6;omitted++){vector<int>left;for(int j=0;j<6;j++)if(j!=omitted)left.push_back(a.ports[j]);rec(left,0,0);}pairsct++;if(pairsct%100==0)cerr<<"pairs "<<pairsct<<" nodes "<<nodes<<" hits "<<hits<<"\n";}cerr<<"FINAL pairs "<<pairsct<<" nodes "<<nodes<<" pruned4 "<<pruned[0]<<" pruned8 "<<pruned[1]<<" pruned16 "<<pruned[2]<<" hits "<<hits<<" seconds "<<chrono::duration<double>(chrono::steady_clock::now()-t).count()<<"\n";}
